{
  "answerable": true,
  "decline_reason": "none",
  "sql": "SELECT p.portfolio_name, SUM(CASE WHEN s.sector_id IN (SELECT sector_id FROM sectors WHERE sector_name = 'Technology') THEN h.quantity * s.current_price ELSE 0 END) AS tech_value, (SUM(CASE WHEN s.sector_id IN (SELECT sector_id FROM sectors WHERE sector_name = 'Technology') THEN h.quantity * s.current_price ELSE 0 END) * 100.0 / SUM(h.quantity * s.current_price)) AS tech_percentage FROM portfolios p JOIN holdings h ON p.portfolio_id = h.portfolio_id JOIN securities s ON h.security_id = s.security_id GROUP BY p.portfolio_id, p.portfolio_name",
  "explanation": "Returns the total value of Technology sector holdings and its percentage of the total portfolio value for each portfolio."
}

{
