  "sql": "SELECT p.portfolio_name, COUNT(DISTINCT s.sector_id) AS distinct_sectors, COUNT(h.holding_id) AS total_holdings, CAST(COUNT(DISTINCT s.sector_id) AS REAL) / COUNT(h.holding_id) AS diversification_ratio FROM portfolios p JOIN holdings h ON p.portfolio_id = h.portfolio_id JOIN securities s ON h.security_id = s.security_id WHERE s.sector_id IS NOT NULL GROUP BY p.portfolio_id, p.portfolio_name HAVING COUNT(DISTINCT s.sector_id) > 5",
  "explanation": "Returns portfolios with holdings in more than 5 distinct sectors along with their calculated diversification metrics."
}

